from pathlib import Path
p=Path('fast_track/v06/direct-layout-0632.css'); s=p.read_text(encoding='utf-8')
s+='''
/* Revisão 0632 — consulta local de cooperados e dados confirmados do risco */
.cooperator-lookup-panel{border:1px solid var(--line);border-radius:18px;background:#f8fbfc;padding:18px;margin:20px 0}
.cooperator-lookup-head{align-items:center}.cooperator-lookup-head .file-button{white-space:nowrap}
.cooperator-base-status{margin:14px 0;padding:13px 15px;border-left:4px solid var(--primary);background:#fff;border-radius:10px;line-height:1.45}
.cooperator-base-status span,.cooperator-base-status small,.cooperator-base-status p{display:block;margin-top:4px;color:var(--muted)}.cooperator-base-status p{margin-bottom:0;font-size:12px}.cooperator-base-warnings{margin-top:8px}.cooperator-base-warnings ul{margin:8px 0 0;padding-left:20px}
.cooperator-results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}.cooperator-result-card{border:1px solid var(--line);border-radius:15px;background:#fff;padding:14px;min-width:0}
.cooperator-result-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.cooperator-result-head h4{margin:0 0 7px;font-size:16px;overflow-wrap:anywhere}.cooperator-result-head .btn{flex:0 0 auto}.cooperator-badges{display:flex;flex-wrap:wrap;gap:6px}.cooperator-badge{display:inline-flex;padding:4px 8px;border-radius:999px;background:#e7f5fb;color:var(--primary-dark);font-size:11px;font-weight:800}
.cooperator-result-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:13px}.cooperator-result-grid div{min-width:0}.cooperator-result-grid span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.04em}.cooperator-result-grid strong{display:block;margin-top:3px;font-size:13px;overflow-wrap:anywhere}.cooperator-result-warning{margin-top:12px;padding:9px 10px;border-radius:9px;background:#fff8e9;color:#785316;font-size:12px}
.cooperator-selected-host{margin-top:18px}.cooperator-selected{border-top:1px solid var(--line);padding-top:18px}.cooperator-installations-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin:18px 0 10px}.cooperator-installations-head h4{margin:0}.cooperator-installation-card{border:1px solid var(--line);border-radius:14px;background:#fff;padding:13px;margin:10px 0}.cooperator-installation-check{font-weight:800;display:flex;align-items:center;gap:8px}
.cooperator-original{margin-top:14px;border:1px solid var(--line);border-radius:12px;background:#fff;padding:10px 12px}.cooperator-original summary{cursor:pointer;font-weight:800}.cooperator-original-meta{display:flex;justify-content:space-between;gap:12px;margin:10px 0;color:var(--muted)}.cooperator-original pre{max-height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f8;padding:12px;border-radius:9px;font-size:11px}
.location-data-block{margin:2mm 0 4mm;break-inside:auto;page-break-inside:auto}.location-data-row{display:grid;grid-template-columns:48mm minmax(0,1fr);column-gap:5mm;align-items:start;padding:.8mm 0;line-height:1.35;break-inside:avoid;page-break-inside:avoid}.location-data-row strong{text-align:left}.location-data-row span{text-align:left;overflow-wrap:anywhere}.location-installations{margin-top:2mm;line-height:1.35}.location-installation-item{display:grid;grid-template-columns:7mm minmax(0,1fr);gap:2mm;padding:1mm 0;break-inside:avoid;page-break-inside:avoid}.location-installation-item small{color:#444;font-size:9.5pt}.location-source-note{margin:2mm 0 0;text-align:left;font-size:9.5pt;color:#444}
@media(max-width:900px){.cooperator-results{grid-template-columns:1fr}.cooperator-result-head,.cooperator-installations-head{flex-direction:column}.cooperator-result-head .btn{width:100%}}@media(max-width:620px){.cooperator-result-grid{grid-template-columns:1fr}.cooperator-lookup-panel{padding:13px}.cooperator-original-meta{flex-direction:column}}
'''
p.write_text(s,encoding='utf-8')
